{"command":"cat <<'PY' > /tmp/pty_finite.py
import pty, os, subprocess, time, struct, fcntl, termios, select
def run_module(m, speed="1000", timeout=8):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 24, 80, 0, 0))
    proc = subprocess.Popen(["./executable","-m",m,"--exit-after-modules","1","--speed-factor",speed],
        stdin=slave, stdout=slave, stderr=slave, close_fds=True)
    os.close(slave)
    os.set_blocking(master, False)
    out=b""
    start=time.time()
    while time.time()-start < timeout:
        if proc.poll() is not None:
            # drain
            try:
                while True:
                    try:
                        d=os.read(master, 8192)
                        if not d: break
                        out+=d
                    except BlockingIOError:
                        break
            except OSError:
                break
            break
        try:
            d=os.read(master, 8192)
            if d: out+=d
        except BlockingIOError:
            time.sleep(0.05)
        except OSError:
            break
    ret=proc.poll()
    if ret is None:
        proc.terminate()
        try: proc.wait(timeout=2)
        except: proc.kill()
        # drain
        try:
            while True:
                try:
                    d=os.read(master, 8192)
                    if not d: break
                    out+=d
                except: break
        except: pass
    os.close(master)
    print(f"{m} speed {speed}: ret={ret} out_len={len(out)} crlf={out.count(bytes([13,10]))}")
    # print snippet
    print(out[:1000].decode(errors='replace')[:500].replace("\r","\\r").replace("\n","\\n\n"))
    print("---tail---")
    print(out[-1000:].decode(errors='replace')[-500:].replace("\r","\\r").replace("\n","\\n\n"))
    print("===")

for m in ["ansible","download","docker_build"]:
    run_module(m, "1000", 8)
