import pty, os, subprocess, time, struct, fcntl, termios
def run(args, timeout=6):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 24, 80, 0, 0))
    proc = subprocess.Popen(args, stdin=slave, stdout=slave, stderr=slave, close_fds=True)
    os.close(slave)
    os.set_blocking(master, False)
    out=b""
    start=time.time()
    while time.time()-start < timeout:
        if proc.poll() is not None:
            try:
                while True:
                    try:
                        d=os.read(master, 8192)
                        if not d: break
                        out+=d
                    except BlockingIOError: break
            except: break
            break
        try:
            d=os.read(master, 8192)
            if d: out+=d
        except BlockingIOError:
            time.sleep(0.05)
        except: break
    ret=proc.poll()
    if ret is None:
        proc.terminate()
        try: proc.wait(timeout=2)
        except: proc.kill()
        try:
            while True:
                try:
                    d=os.read(master, 8192)
                    if not d: break
                    out+=d
                except: break
        except: pass
    os.close(master)
    txt=out.decode(errors='replace')
    print(f"args={args} ret={ret} len={len(out)}")
    # check for module signatures
