use clap::{Parser, CommandFactory, ValueEnum};
use std::io::Write;

#[derive(Debug, Clone, ValueEnum)]
enum Module {
    ansible,
    bootlog,
    botnet,
    bruteforce,
    cargo,
    cc,
    composer,
    cryptomining,
    docker_build,
    docker_image_rm,
    download,
    julia,
    kernel_compile,
    memdump,
    mkinitcpio,
    rkhunter,
    simcity,
    terraform,
    uv,
    weblog,
    wpt,
}

#[derive(Debug, Clone, ValueEnum)]
enum Shell {
    bash,
    elvish,
    fish,
    powershell,
    zsh,
}

fn parse_speed(s: &str) -> Result<f64, String> {
    let v: f64 = s.parse().map_err(|_| "invalid float literal".to_string())?;
    if v <= 0.01 {
        return Err("Speed factor must be larger than 0.01".to_string());
    }
    Ok(v)
}

fn parse_exit_modules(s: &str) -> Result<u64, String> {
    let v: u64 = s.parse().map_err(|_| "invalid digit found in string".to_string())?;
    if v == 0 {
        return Err("Must be larger than 0".to_string());
    }
    Ok(v)
}

fn parse_duration(s: &str) -> Result<String, String> {
    // placeholder, just test humantime-like errors for now
    // We'll implement real later, for now just accept anything
    if s == "abc" {
        return Err("expected number at 0".to_string());
    }
    Ok(s.to_string())
}

#[derive(Parser, Debug)]
#[command(name = "genact", version = "1.5.1", about = "A nonsense activity generator")]
struct Args {
    #[arg(short, long, help = "List available modules")]
    list_modules: bool,
    #[arg(short, long, help = "Run only these modules")]
    modules: Vec<Module>,
    #[arg(short, long, default_value_t = 1.0, value_parser = parse_speed, help = "Global speed factor")]
    speed_factor: f64,
    #[arg(short, long, default_value_t = 0, help = "Instantly print this many lines")]
    instant_print_lines: u32,
    #[arg(long, help = "Keep the computer awake and the display on while genact is running")]
    inhibit: bool,
    #[arg(long, value_parser = parse_duration, help = "Exit after running for this long (format example: 2h10min)")]
    exit_after_time: Option<String>,
    #[arg(long, value_parser = parse_exit_modules, help = "Exit after running this many modules")]
    exit_after_modules: Option<u64>,
    #[arg(long, help = "Generate completion file for a shell")]
    print_completions: Option<Shell>,
    #[arg(long, help = "Generate man page")]
    print_manpage: bool,
}

fn main() {
    let args = Args::parse();
    if let Some(shell) = args.print_completions {
        let mut cmd = Args::command();
        let name = "genact";
        match shell {
            Shell::bash => clap_complete::generate(clap_complete::shells::Bash, &mut cmd, name, &mut std::io::stdout()),
