        // major 0-50? minor 0-40? patch 0-60?
        // Sometimes "0.0.0", "1.0.0", etc.
        // We'll generate random: major 0-5? But observed 47, 17, etc. So major up to 50?
        // Let's do: 70% small (0-5), 30% large (0-50)
        let major = if self.gen_bool(0.7) { self.gen_range(0, 6) } else { self.gen_range(0, 50) };
