// IO helpers: printing with \r\n, width detection, panic handling, sleep with speed/instant/signals
use std::io::Write;
use std::sync::atomic::{AtomicBool, Ordering};
use std::time::{Duration, Instant};

pub static SHOULD_EXIT: AtomicBool = AtomicBool::new(false);

pub fn install_signal_handlers() {
    unsafe {
        // Use sigaction for SIGTERM, SIGINT, SIGHUP
        for sig in [libc::SIGTERM, libc::SIGINT, libc::SIGHUP] {
            let mut sa: libc::sigaction = std::mem::zeroed();
            sa.sa_sigaction = handler as usize;
            sa.sa_flags = 0;
            libc::sigemptyset(&mut sa.sa_mask);
            libc::sigaction(sig, &sa, std::ptr::null_mut());
        }
        // Ignore SIGPIPE (Rust does by default, but ensure)
        libc::signal(libc::SIGPIPE, libc::SIG_IGN);
    }
}

extern "C" fn handler(_sig: libc::c_int) {
    SHOULD_EXIT.store(true, Ordering::SeqCst);
}

pub fn should_exit() -> bool {
    SHOULD_EXIT.load(Ordering::SeqCst)
}

pub fn reset_exit() {
    SHOULD_EXIT.store(false, Ordering::SeqCst);
}

// Context for printing: speed, instant remaining, start time, exit-after-time
pub struct Ctx {
    pub speed_factor: f64,
    pub instant_remaining: u64,
    pub start: Instant,
    pub exit_after_time: Option<Duration>,
}

impl Ctx {
    pub fn new(speed_factor: f64, instant: u32, start: Instant, exit_after_time: Option<Duration>) -> Self {
        Self {
            speed_factor,
            instant_remaining: instant as u64,
            start,
            exit_after_time,
        }
    }
    pub fn check_exit_time(&self) -> bool {
        if let Some(d) = self.exit_after_time {
            if self.start.elapsed() >= d {
                return true;
            }
        }
        false
    }
    // sleep, returns true if should exit (signal or time)
    pub fn sleep(&mut self, base_ms: u64) -> bool {
        if should_exit() || self.check_exit_time() {
            return true;
        }
        if self.instant_remaining > 0 {
            self.instant_remaining -= 1;
            // still need to check exit? No sleep
            return should_exit() || self.check_exit_time();
        }
        if base_ms == 0 {
            return should_exit() || self.check_exit_time();
        }
        let ms = (base_ms as f64 / self.speed_factor) as u64;
