        } else {
            panic_broken_pipe();
        }
    }
    if let Err(e) = h.write_all(b"\r\n") {
        if e.kind() == std::io::ErrorKind::BrokenPipe {
            panic_broken_pipe();
        } else {
            panic_broken_pipe();
        }
    }
    if let Err(e) = h.flush() {
        if e.kind() == std::io::ErrorKind::BrokenPipe {
            panic_broken_pipe();
        }
    }
}

pub fn print_raw(s: &[u8]) {
    let stdout = std::io::stdout();
    let mut h = stdout.lock();
    if let Err(e) = h.write_all(s) {
        if e.kind() == std::io::ErrorKind::BrokenPipe {
            panic_broken_pipe();
        } else {
            panic_broken_pipe();
        }
    }
    if let Err(e) = h.flush() {
        if e.kind() == std::io::ErrorKind::BrokenPipe {
            panic_broken_pipe();
        }
    }
}

pub fn print_raw_str(s: &str) {
    print_raw(s.as_bytes());
}

pub fn get_terminal_width() -> usize {
    unsafe {
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(libc::STDOUT_FILENO, libc::TIOCGWINSZ, &mut ws) == 0 {
