fn run_cryptomining_full(ctx: &mut Ctx, rng: &mut Rng) -> bool {
    let n = rng.gen_range(200, 800) as usize;
    let ngpus = rng.gen_range(3, 7) as usize; // 3-6? observed 6 (0-5) and 3 (0-2)
    // initial time? Original shows time 17:09:35 (current time?) and Time: 00:00 (elapsed?). Need to use current time? Or fixed?
    // Use chrono? We'll use SystemTime to get HH:MM:SS UTC? Original shows 17:09:35 UTC? Our test at 17:23, original showed 17:23. So it uses current time.
    // We'll get current time via SystemTime and format as HH:MM:SS (UTC? local? Use UTC? We'll just use local? Simplify: use fixed 17:09:35? Better to use actual time to match.
    // For elapsed Time: 00:00 always? In sample, Time: 00:00 for all lines (since fast, <1min). With longer runs, it would increase? Let's just keep 00:00.
    // Accepted shares: [A0+0:R0+0:F0] initially, later [A5+0...]? In sample tail, A5. So accepted increases over time.
    let mut accepted = 0;
    for i in 0..n {
        if should_exit() || ctx.check_exit_time() { return true; }
        // time string: current time? We'll compute
        let now = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_secs();
        // convert to HH:MM:SS UTC (mod 86400)
        let secs_day = now % 86400;
        let hh = secs_day / 3600;
        let mm = (secs_day % 3600) / 60;
        let ss = secs_day % 60;
        let timestr = format!("{:02}:{:02}:{:02}", hh, mm, ss);
        // speeds: total ~ 178-232, per gpu ~29-77? For 6 gpus, total ~178 (29*6), for 3 gpus, total ~232 (77*3). So per gpu ~30 or ~77 depending? Let's generate per gpu 29-31 for 6, 77-78 for 3? Actually observed 6 gpus with 29-30 each, 3 gpus with 77 each. So total ~180 or ~230. We'll generate accordingly.
        let per_gpu_base = if ngpus <= 3 { 77.0 } else { 29.5 };
        let mut gpu_speeds = Vec::new();
        let mut total = 0.0;
        for _ in 0..ngpus {
            let s = per_gpu_base + (rng.gen_range(0, 100) as f64 / 100.0 * 2.0 - 1.0); // +-1
            gpu_speeds.push(s);
            total += s;
        }
        // randomly increase accepted every ~100 lines?
        if i > 0 && i % rng.gen_range(80, 150) as usize == 0 {
            accepted += 1;
        }
        let mut line = format!("\x1b[32m  m\x1b[0m  \x1b[35m{}\x1b[0m\x1b[30m|\x1b[0m\x1b[34mcryptominer  \x1b[0mSpeed \x1b[1;36m{:.2}\x1b[0m Mh/s    ", timestr, total);
        for (idx, s) in gpu_speeds.iter().enumerate() {
            line.push_str(&format!("gpu/{} \x1b[36m{:.2}\x1b[0m ", idx, s));
        }
        line.push_str(&format!("  [A{}+0:R0+0:F0] Time: 00:00", accepted));
        print_line(ctx, &line);
        if ctx.sleep(5 + rng.gen_range(0, 10)) { return true; }
    }
    false
}

