// ===== CARGO (simple, already understood) =====
fn run_cargo(ctx: &mut Ctx, rng: &mut Rng) -> bool {
    let n = rng.gen_range(10, 100) as usize;
    let mut pkgs: Vec<(String,String)> = Vec::new();
    for _ in 0..n {
        let name = gen_cargo_name(rng);
        let ver = rng.gen_version();
        pkgs.push((name, ver));
    }
    for (name, ver) in &pkgs {
        if should_exit() || ctx.check_exit_time() { return true; }
        let line = format!("\x1b[1;32m Downloading\x1b[0m {} v{}", name, ver);
        print_line(ctx, &line);
        if ctx.sleep((80 as f64 + rng.gen_range(0, 80) as f64) as u64) { return true; }
    }
    for (name, ver) in &pkgs {
        if should_exit() || ctx.check_exit_time() { return true; }
        let line = format!("\x1b[1;32m   Compiling\x1b[0m {} v{}", name, ver);
        print_line(ctx, &line);
        if ctx.sleep((80 as f64 + rng.gen_range(0, 80) as f64) as u64) { return true; }
    }
    let t = format!("0.{:02}", rng.gen_range(5, 35));
    let line = format!("\x1b[1;32m    Finished\x1b[0m release [optimized] target(s) in {} secs", t);
    print_line(ctx, &line);
    if ctx.sleep(100) { return true; }
    false
}

fn gen_cargo_name(rng: &mut Rng) -> String {
    // generate plausible crate name: combine words
    const WORDS: &[&str] = &["rust","cargo","tokio","serde","async","sync","core","sys","cli","api","lib","net","http","grpc","aws","google","azure","db","sql","redis","mongo","kafka","docker","k8s","linux","windows","macos","android","ios","wasm","ffi","bindgen","derive","macro","plugin","util","common","shared","test","mock","fake","rand","crypto","hash","compress","image","video","audio","text","json","yaml","toml","xml","csv","log","trace","metrics","auth","oauth","jwt","tls","ssl","ssh","ftp","smtp","dns","dhcp","firewall","proxy","cache","queue","stack","heap","tree","graph","map","set","vec","string","bytes","time","date","chrono","uuid","rand","regex","parser","lexer","compiler","vm","jit","lsp","dap","debug","profile","bench","fuzz","audit","lint","fmt","clippy","miri","cargo","rustc","rustdoc","rustfmt"];
    // sometimes single word, sometimes word-word, word_word, word-word-sys, etc.
    let style = rng.gen_range(0, 10);
    match style {
        0..=2 => format!("{}", rng.choose(WORDS)),
        3..=5 => format!("{}-{}", rng.choose(WORDS), rng.choose(WORDS)),
        6 => format!("{}_{}", rng.choose(WORDS), rng.choose(WORDS)),
        7 => format!("{}-sys", rng.choose(WORDS)),
        8 => format!("{}-cli", rng.choose(WORDS)),
        _ => format!("{}{}", rng.choose(WORDS), rng.gen_range(0, 9)),
    }
}

// ===== MEMDUMP =====
fn run_memdump(ctx: &mut Ctx, rng: &mut Rng) -> bool {
    let n = rng.gen_range(30, 150) as usize;
    let base: u64 = rng.gen_u64() & 0xfffffffffffff000;
    // align base to 0x10? original addresses like 4df2ad8b1e0d7e80 (ends with 80,90,a0... step 0x10)
    let mut addr = base & !0xf;
    // ensure last nibble? original starts with ...e80, then ...e90, ...ea0 (step 0x10). Good.
    for _ in 0..n {
        if should_exit() || ctx.check_exit_time() { return true; }
        let mut bytes = [0u8; 16];
        for b in bytes.iter_mut() {
            *b = rng.gen_range(0, 256) as u8;
        }
        // format: addr (16 hex, lowercase) + "  " + hex bytes with spaces, double space after 8, + "  |ascii|"
        // e.g., "4df2ad8b1e0d7e80  be 4e f5 3b dd 3d a0 77  e6 cf b2 94 68 1c a9 a6  |.N.;.=.w....h...|"
        let mut hex_part = String::new();
        for (i, b) in bytes.iter().enumerate() {
            if i == 8 {
                hex_part.push(' ');
            }
            hex_part.push_str(&format!("{:02x} ", b));
        }
        // hex_part has trailing space, need to remove? Original: "be 4e ... a6  " (two spaces before |)? Let's match: after 16 bytes, two spaces then |.
        // Our hex_part: "be 4e ... 77  e6 ... a6 " (with extra space at 8, trailing space). Good.
        // ascii: '.' for non-printable? Original uses '.' for <32 or >126? Check: bytes like 0xbe -> '.'? Yes.
        let mut ascii = String::new();
        for b in bytes.iter() {
            if *b >= 32 && *b <= 126 {
                ascii.push(*b as char);
            } else {
                ascii.push('.');
            }
        }
        let line = format!("{:016x}  {} |{}|", addr, hex_part.trim_end(), ascii);
        // Need to ensure spacing: original has two spaces between addr and hex, and two spaces between hex and |? Let's check: "4df2...e80  be 4e..." (two spaces), "...a6  |.N..." (two spaces). Our format: "{:016x}  {} |{}|" -> addr + two spaces + hex_trimmed + space + |...|? Actually we need two spaces before |.
        // hex_trimmed ends without trailing space, then "  |" (two spaces + |)? Our format has " |" (one space). Fix to "  |".
        // Redo:
        let line2 = format!("{:016x}  {}  |{}|", addr, hex_part.trim_end(), ascii);
        print_line(ctx, &line2);
        addr = addr.wrapping_add(0x10);
        if ctx.sleep(30 + rng.gen_range(0, 50)) { return true; }
    }
    false
}

