        let mut total = 0.0;
        for _ in 0..ngpus {
            let s = per_gpu_base + (rng.gen_range(0, 100) as f64 / 100.0 * 2.0 - 1.0); // +-1
            gpu_speeds.push(s);
            total += s;
        }
        // randomly increase accepted every ~100 lines?
        if i > 0 && i % rng.gen_range(80, 150) as usize == 0 {
            accepted += 1;
        }
        let mut line = format!("\x1b[32m  m\x1b[0m  \x1b[35m{}\x1b[0m\x1b[30m|\x1b[0m\x1b[34mcryptominer  \x1b[0mSpeed \x1b[1;36m{:.2}\x1b[0m Mh/s    ", timestr, total);
        for (idx, s) in gpu_speeds.iter().enumerate() {
            line.push_str(&format!("gpu/{} \x1b[36m{:.2}\x1b[0m ", idx, s));
        }
        line.push_str(&format!("  [A{}+0:R0+0:F0] Time: 00:00", accepted));
        print_line(ctx, &line);
        if ctx.sleep(5 + rng.gen_range(0, 10)) { return true; }
    }
    false
}

