import pty, os, subprocess, time, struct, fcntl, termios
def test(binpath, cols):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 24, cols, 0, 0))
    proc = subprocess.Popen([binpath,"-m","download","--speed-factor","100"], stdin=slave, stdout=slave, stderr=slave, close_fds=True)
    os.close(slave)
    os.set_blocking(master, False)
    out=b""
    start=time.time()
    while time.time()-start < 2:
        if proc.poll() is not None:
            break
        try:
            d=os.read(master, 8192)
            if d: out+=d
        except BlockingIOError:
            time.sleep(0.05)
        except: break
    if proc.poll() is None:
        proc.terminate()
        try: proc.wait(timeout=2)
        except: proc.kill()
    try: os.close(master)
    except: pass
    txt=out.decode(errors='replace')
    print(f"{binpath} cols={cols}: len={len(out)} small={txt.count('Terminal too small')}")
for cols in [40,55,80]:
    test("./executable", cols)
    test("/tmp/executable", cols)
